  });

  it('normalises email to lowercase', async () => {
    mocks.organisationFindUnique.mockResolvedValue({ id: ORG_ID });

    const inv = await createInvitation({
      orgId: ORG_ID,
      email: 'USER@EXAMPLE.COM',
      role: 'CONSULTANT',
      actingUserId: ACTING_USER,
