    // Reset call count to verify second call doesn't create another audit entry
    mocks.appendDomainAudit.mockClear();

    const second = await createInvitation({
      orgId: ORG_ID,
      email: 'dup@example.com',
      role: 'CONSULTANT',
      actingUserId: ACTING_USER,
